if (!/^\d+_[\w\d]{16,}/.test(token)) {
    java.longToast("❌ 尚未登录或登录信息无效\n请先登录：书源管理 → 晋江 → 登录（支持账密/扫码）\n登录后回到本章再执行购买即可。");
    result = false;
} else {
    var balMsg = "";
    try {
        var bSign = encode(String(Date.now()) + ":" + token);
        var bUrl = "https://app.jjwxc.org/androidapi/getUserBalance?versionCode=381&token=" + token + "&sign=" + encodeURIComponent(bSign);
        var bResp = String(java.ajax(bUrl));
        var bJson = JSON.parse(bResp);
        var bal = bJson.balance !== undefined ? bJson.balance : (bJson.data && bJson.data.balance);
        if (bal !== undefined && String(bal) !== "" && String(bJson.code || "") !== "1004") {
            balMsg = "💰 当前余额：" + bal + " 晋江币\n";
        }
    } catch (eb) {
        java.log("balance check error: " + eb);
    }

    enbody = String(Date.now()) + ":" + token + ":" + nid;
    sign = encode(enbody);
    q = "versionCode=381&novelId=" + nid + "&chapters=" + cid + "&orderType=15&isautoBuy=0&autosubscribeStatus=0&notUseBackpoint=&sign=" + encodeURIComponent(sign);
    url = "https://android.jjwxc.net/androidapi/buy?" + q;
    try {
        a = String(java.ajax(url));
        java.log("buy resp: " + a.slice(0, 300));
        var r = JSON.parse(a);
        var msg = String(r.message || "");
        var code = String(r.code || "");
        if (/购买成功/.test(msg)) {
            java.longToast("✅ " + msg + "\n" + balMsg + "本章将自动刷新，无需手动操作。");
            result = true;
        } else if (code == "1004" || /登入验证失败/.test(msg)) {
            java.longToast("❌ 登录已过期（1004）\n请重新登录：书源管理 → 晋江 → 登录\n（token 有效期约 1 小时，重新登录后可直接重试购买）");
            result = false;
        } else if (/余额/.test(msg) || /不足/.test(msg)) {
            java.longToast("❌ " + balMsg + msg + "\n请到晋江App/官网充值晋江币后重试。");
            result = false;
        } else {
            var popup = "";
            if (r.popupdata && r.popupdata.popupmessage) {
                popup = String(r.popupdata.popupmessage);
            }
            var mm = msg || popup || "购买失败（未知原因），请截图错误信息反馈。";
            if (popup && !/APP/.test(mm)) {
                mm += "\n❗️如反复失败，请进晋江App进行一次账号验证后，方可在阅读APP使用购买功能。";
            }
            java.longToast(balMsg + "❌ " + mm);
            result = false;
        }
    } catch (e) {
        java.log("payAction error: " + e);
        java.longToast(balMsg + "❌ 购买请求异常：" + e + "\n请检查网络后重试；若反复失败请进晋江App完成一次账号验证。");
        result = false;
    }
}

